  "program": "two_workers",
  "version": "3.5.0",
  "entry": "main::main",
  "modules": [
    {
      "name": "main",
      "provides": {
        "resources": ["counter", "done"],
        "functions": ["main", "supervisor", "worker"]
      },
      "requires": {
        "resources": [],
        "functions": []
      },
      "resources": [
        {
          "name": "counter",
          "kind": "var",
          "type": "Atomic",
          "base": "Int",
          "init": 0
        },
        {
          "name": "done",
          "kind": "var",
          "type": "Var",
          "base": "Bool",
          "init": false
        }
      ],
      "protection": [],
      "functions": [
        {
          "name": "main",
          "kind": "normal",
          "form": "closure",
          "body": [
            {
              "sid": "s1",
              "kind": "call",
              "func": "main::supervisor"
            },
            {
              "sid": "s2",
              "kind": "return"
            }
          ]
        },
        {
          "name": "supervisor",
          "kind": "normal",
          "form": "closure",
          "body": [
            {
              "sid": "s1",
              "kind": "scope",
              "funcs": ["main::worker", "main::worker"]
            },
            {
              "sid": "s2",
              "kind": "write_shared",
              "resource": "main::done",
              "expr": "true"
            },
            {
              "sid": "s3",
              "kind": "return"
            }
          ]
        },
        {
          "name": "worker",
          "kind": "normal",
          "form": "closure",
          "body": [
            {
              "sid": "s1",
              "kind": "atomic_load",
              "resource": "main::counter",
              "dst": "old"
            },
            {
              "sid": "s2",
              "kind": "assign_local",
              "target": "new",
              "expr": "old + 1"
            },
            {
              "sid": "s3",
              "kind": "atomic_cas",
              "resource": "main::counter",
              "expected": "old",
              "desired": "new",
              "dst": "ok"
            },
            {
              "sid": "s4",
              "kind": "branch",
              "cond": "ok == true",
              "then": "s5",
              "else": "s1"
            },
            {
              "sid": "s5",
              "kind": "return"
            }
          ]
        }
      ]
    }
  ]
}
</previous_candidate>

